-- ── Q1: Cephalosporins — cefixime, loracarbef ─────────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Antimicrobials','The drugs classified as cephalosporins include:','Cefixime, Loracarbef','Cephradine, Laroxyl','Ceftriaxone, Lasix','Cefaclor, Clonazepam','A','Cefixime is a 3rd-generation cephalosporin and loracarbef is a carbacephem (structurally related); the distractors pair cephalosporins with non-cephalosporins such as amitriptyline (Laroxyl), furosemide (Lasix) and clonazepam (BNF antibacterials).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Antimicrobials','The drugs classified as cephalosporins include:','Cefixime, Loracarbef','Cephradine, Laroxyl','Ceftriaxone, Lasix','Cefaclor, Clonazepam','A','Cefixime and loracarbef belong to the beta-lactam/cephalosporin class; nurses must distinguish them from other drug classes when selecting antibiotic therapy and monitoring for class-specific reactions (BNF; pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q2: Antitussives — relieve dry cough ──────────────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Respiratory Pharmacology','Antitussive agents are indicated to:','Remove secretions','Relieve rhinitis','Control productive cough','Relieve a dry cough','D','Antitussives suppress the cough reflex and are indicated for a dry, non-productive cough; expectorants (not antitussives) facilitate removal of secretions (BNF/pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Respiratory Pharmacology','Antitussive agents are indicated to:','Remove secretions','Relieve rhinitis','Control productive cough','Relieve a dry cough','D','Antitussives (e.g. dextromethorphan, codeine) suppress the cough centre; use in dry cough only — contraindicated when cough is clearing secretions. Nurses differentiate from mucolytics and expectorants (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q3: Narcotic analgesics — codeine, morphine ───────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Analgesics','The drugs classified as narcotic analgesics include:','Acetylsalicylic acid, Indomethacin','Acetaminophen, Ibuprofen','Codeine, Morphine','Morphine, Diclofenac','C','Codeine and morphine are opioid (narcotic) analgesics; aspirin, paracetamol, ibuprofen and diclofenac are non-opioid/NSAID agents (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Analgesics','The drugs classified as narcotic analgesics include:','Acetylsalicylic acid, Indomethacin','Acetaminophen, Ibuprofen','Codeine, Morphine','Morphine, Diclofenac','C','Opioid analgesics act on mu/kappa receptors; nurses apply WHO analgesic ladder principles, monitor for respiratory depression and constipation, and manage controlled drug protocols (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q4: Hypnotics — induce sleep ──────────────────────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','CNS Pharmacology','The action of hypnotic drugs is to induce:','Vomiting','Appetite','Sleep','Calmness','C','Hypnotic drugs are given specifically to induce sleep; sedatives produce calmness/drowsiness without necessarily inducing sleep (BNF/pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','CNS Pharmacology','The action of hypnotic drugs is to induce:','Vomiting','Appetite','Sleep','Calmness','C','Hypnotics (e.g. zolpidem, temazepam) induce and maintain sleep; sedatives reduce anxiety. Nurses assess sleep hygiene, risk of dependence, and residual sedation in older adults (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q5: Antidote for morphine — naloxone ──────────────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Antidotes','The antidote for morphine toxicity is:','Methadone','Fentanyl','Amphetamine','Naloxone','D','Naloxone is the specific opioid antagonist used to reverse morphine (opioid) toxicity and respiratory depression (BNF; MOH Kenya poisoning protocols).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Antidotes','The antidote for morphine toxicity is:','Methadone','Fentanyl','Amphetamine','Naloxone','D','Naloxone reverses all opioid effects including respiratory depression; its short half-life may require repeat doses or infusion. Nurses monitor for re-narcotisation and acute withdrawal (BNF; MOH Kenya poisoning protocols).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q6: Bioavailability — absorption and transport to target tissue ────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Pharmacokinetics','The extent to which a drug is absorbed and transported to the target tissue is known as:','Steady-state accumulation','Therapeutic drug level','Bioavailability','Distribution','C','Bioavailability is the proportion of an administered dose that reaches the systemic circulation and thus the target tissue (pharmacokinetics; Brunner & Suddarth).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Pharmacokinetics','The extent to which a drug is absorbed and transported to the target tissue is known as:','Steady-state accumulation','Therapeutic drug level','Bioavailability','Distribution','C','Bioavailability (F) is affected by route, first-pass metabolism and formulation; IV = 100%. Understanding bioavailability guides dose adjustments when switching routes (BNF; pharmacokinetics).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q7: Pharmacokinetics — actions of body on drug ────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Pharmacokinetics','The actions of the body on the drug are referred to as:','Pharmacodynamics','Pharmacokinetics','Pharmacognosy','Pharmacogenomics','B','Pharmacokinetics describes what the body does to the drug — absorption, distribution, metabolism and excretion (ADME); pharmacodynamics is what the drug does to the body (standard pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Pharmacokinetics','The actions of the body on the drug are referred to as:','Pharmacodynamics','Pharmacokinetics','Pharmacognosy','Pharmacogenomics','B','Pharmacokinetics (ADME) determines drug plasma levels and dosing intervals; nurses apply PK principles to recognise accumulation in renal/hepatic impairment and adjust timing of monitoring (BNF; pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q8: Mannitol — osmotic diuretic ──────────────────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Diuretics','Mannitol is classified as:','Potassium-wasting diuretic','Loop diuretic','Osmotic diuretic','Potassium-sparing diuretic','C','Mannitol is an osmotic diuretic used to reduce raised intracranial or intraocular pressure by drawing fluid from tissues into the circulation (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Diuretics','Mannitol is classified as:','Potassium-wasting diuretic','Loop diuretic','Osmotic diuretic','Potassium-sparing diuretic','C','Mannitol osmotically draws water into the vascular space; used in raised ICP and acute closed-angle glaucoma. Nurses monitor serum osmolality and electrolytes (BNF; critical care pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q9: Atenolol — beta blocker ───────────────────────────────────────────────
