VALUES('KRCHN','Paper I','Pharmacology','Cardiovascular Pharmacology','Atenolol is classified as:','Beta-2 agonist','Beta blocker','ACE inhibitor','Calcium channel blocker','B','Atenolol is a cardioselective beta-adrenoceptor blocker used in hypertension, angina and dysrhythmias (BNF cardiovascular drugs).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Cardiovascular Pharmacology','Atenolol is classified as:','Beta-2 agonist','Beta blocker','ACE inhibitor','Calcium channel blocker','B','Atenolol (cardioselective beta-1 blocker) reduces heart rate and BP; contraindicated in asthma and heart block. Nurses monitor pulse before administration (BNF; Brunner & Suddarth).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

