INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Antimicrobials','The drugs classified as penicillins include:','Methicillin Sodium, Nafcillin Sodium','Penicillin V, Ciprofloxacin','Ampicillin, Doxycycline','Erythromycin, Sotalol','A','Methicillin sodium and nafcillin sodium are both penicillinase-resistant penicillins; other options pair penicillins with fluoroquinolones, tetracyclines or macrolides (BNF antibacterials).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Antimicrobials','The drugs classified as penicillins include:','Methicillin Sodium, Nafcillin Sodium','Penicillin V, Ciprofloxacin','Ampicillin, Doxycycline','Erythromycin, Sotalol','A','Penicillinase-resistant penicillins (methicillin, nafcillin) target MSSA; nurses must distinguish penicillin subclasses for MRSA vs sensitive staphylococci and monitor for anaphylaxis (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q11: Digitalis toxicity — cardiac arrhythmias ─────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Cardiovascular Pharmacology','The major sign of digitalis toxicity is:','Cardiac arrhythmias','Paraesthesia','Excessive slowing of pulse','Generalised muscle weakness','A','Digitalis (digoxin) toxicity chiefly manifests as cardiac arrhythmias — bradycardia, AV block, atrial tachycardia with block, ectopic beats (BNF; Brunner & Suddarth cardiac glycoside pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Cardiovascular Pharmacology','The major sign of digitalis toxicity is:','Cardiac arrhythmias','Paraesthesia','Excessive slowing of pulse','Generalised muscle weakness','A','Digoxin toxicity (narrow therapeutic index) presents with arrhythmias, nausea, visual disturbances; nurses check apical pulse <60 bpm before dosing and monitor digoxin levels and potassium (BNF; Brunner & Suddarth).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q12: Antiulcer agents — famotidine, sucralfate ────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Gastrointestinal Pharmacology','The antiulcer agents include:','Cimetidine, Amitriptyline','Omeprazole, Tramadol','Famotidine, Sucralfate','Praziquantel, Ranitidine Hydrochloride','C','Famotidine (H2-receptor antagonist) and sucralfate (mucosal protectant) are both antiulcer agents; other distractors pair antiulcer drugs with antidepressants, opioids or anthelmintics (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Gastrointestinal Pharmacology','The antiulcer agents include:','Cimetidine, Amitriptyline','Omeprazole, Tramadol','Famotidine, Sucralfate','Praziquantel, Ranitidine Hydrochloride','C','Famotidine reduces gastric acid secretion; sucralfate forms a protective barrier over ulcer base. Nurses schedule antacids and sucralfate away from other medications to prevent absorption interference (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q13: Praziquantel contraindication — ocular cysticercosis ─────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Antiparasitic Drugs','The major contraindication to praziquantel is use in patients with:','Hepatic dysfunction','Ocular cysticercosis','Lymphadenopathy','Peptic ulcer disease','B','Praziquantel is contraindicated in ocular cysticercosis because parasite destruction inside the eye triggers an intense inflammatory response that can cause irreparable ocular damage (BNF/anthelmintic guidelines).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Antiparasitic Drugs','The major contraindication to praziquantel is use in patients with:','Hepatic dysfunction','Ocular cysticercosis','Lymphadenopathy','Peptic ulcer disease','B','In ocular cysticercosis, praziquantel-induced parasite lysis in the eye causes local inflammatory destruction; surgical removal is preferred. Nurses screen patients for eye involvement before prescribing (BNF; Kenya NTD guidelines).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q14: Half-life — concentration reduced by half ────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Pharmacokinetics','The time required to reduce the concentration of a drug in the body by one half is called:','Time course','Time period','Half-life','Half lifespan','C','Half-life (t½) is the time for plasma drug concentration to fall by 50%; it determines dosing frequency and time to steady state (pharmacokinetics; Brunner & Suddarth).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Pharmacokinetics','The time required to reduce the concentration of a drug in the body by one half is called:','Time course','Time period','Half-life','Half lifespan','C','t½ governs dosing intervals; ~4–5 half-lives to reach steady state. Extended in renal/hepatic disease — nurses adjust monitoring frequency accordingly (BNF; pharmacokinetics).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q15: Nifedipine mechanism — inhibits calcium influx ───────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Cardiovascular Pharmacology','The mode of action of nifedipine (Adalat) is that it:','Inhibits calcium ion influx across cardiac and smooth muscle cells, decreasing myocardial contractility and oxygen demand','Stabilises neuronal membrane and limits seizure activity by decreasing sodium influx','Depresses monosynaptic transmission in the CNS and raises the seizure threshold','Increases norepinephrine and serotonin in the CNS by blocking their reuptake','A','Nifedipine is a dihydropyridine calcium-channel blocker that inhibits calcium influx across cardiac and vascular smooth muscle, reducing contractility and peripheral resistance (BNF cardiovascular drugs).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Cardiovascular Pharmacology','The mode of action of nifedipine (Adalat) is that it:','Inhibits calcium ion influx across cardiac and smooth muscle cells, decreasing myocardial contractility and oxygen demand','Stabilises neuronal membrane and limits seizure activity by decreasing sodium influx','Depresses monosynaptic transmission in the CNS and raises the seizure threshold','Increases norepinephrine and serotonin in the CNS by blocking their reuptake','A','Nifedipine inhibits L-type Ca²⁺ channels; used in hypertension, angina. Peripheral vasodilation may cause reflex tachycardia. Nurses monitor BP, pulse, and peripheral oedema (BNF; Brunner & Suddarth).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

