INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Respiratory Pharmacology','The following drugs are bronchodilators:','Aminophylline, Nifedipine','Theophylline, Amiloride','Amoline, Aminophylline','Amiloride, Amitriptyline','C','Amoline and aminophylline are methylxanthine bronchodilators that inhibit phosphodiesterase; nifedipine is a calcium-channel blocker and amiloride is a potassium-sparing diuretic (BNF respiratory drugs).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Respiratory Pharmacology','The following drugs are bronchodilators:','Aminophylline, Nifedipine','Theophylline, Amiloride','Amoline, Aminophylline','Amiloride, Amitriptyline','C','Methylxanthines (aminophylline/theophylline) have a narrow therapeutic index; nurses monitor serum levels, toxicity signs (tachycardia, seizures) and drug interactions (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q20: Naloxone — pure narcotic antagonist with no agonistic activity ────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Antidotes','Naloxone is the drug of choice for narcotic toxicity because it:','Exerts both antagonist and agonist activity','Is a pure narcotic antagonist with no agonistic activity','Is effective for respiratory depression caused by other CNS depressants','Has no narcotic action','B','Naloxone is a pure opioid receptor antagonist with no intrinsic agonist activity, making it safe and specific for reversing opioid toxicity without producing euphoria or dependence (BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Antidotes','Naloxone is the drug of choice for narcotic toxicity because it:','Exerts both antagonist and agonist activity','Is a pure narcotic antagonist with no agonistic activity','Is effective for respiratory depression caused by other CNS depressants','Has no narcotic action','B','Naloxone''s lack of agonist activity makes it safe; it does NOT reverse benzodiazepine or barbiturate depression. Nurses differentiate mixed overdose presentations and titrate dose carefully to avoid precipitating acute withdrawal (BNF; MOH Kenya poisoning guidelines).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

