INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Antimicrobials','Cephalosporin drugs include:','Cefotaxime sodium, Precef, Cefotan','Cefotan, Cefoxitin sodium, Carbinoxamine','Ceftizoxime sodium, Cefuroxime, Carbamazepine','Cephalexin, Cephradine, Carmustine','A','Nurses must identify cephalosporin generations to anticipate spectrum of activity and cross-reactivity with penicillin allergy (BNF; Brunner & Suddarth antimicrobial pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q22: Emergency route — intravenous injection ──────────────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Pharmacokinetics','The most appropriate route of drug administration in an emergency is:','Intramuscular injection','Intravenous injection','Oral administration','Per rectum','B','Intravenous injection provides immediate, 100% bioavailability and the most rapid onset of action, making it the preferred route in emergencies (Kenya Basic Paediatric Protocols; Brunner & Suddarth).','medium',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Pharmacokinetics','The most appropriate route of drug administration in an emergency is:','Intramuscular injection','Intravenous injection','Oral administration','Per rectum','B','IV route bypasses absorption, giving immediate drug availability; critical in cardiac arrest, anaphylaxis and status epilepticus. Nurses must maintain IV access and competence in emergency drug administration (BNF; Brunner & Suddarth).','medium',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q23: Suboptimal drug use — dose too small, course too short ───────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Pharmacokinetics','Suboptimal use of a drug may lead to treatment failure due to:','Too small a dose and late treatment','Unstable route and too long an interval between doses','Unsuitable route and high incidence of drug reactions','Duration of course too short and dose too small','D','Sub-therapeutic dosing — course duration too short or dose too small — fails to achieve adequate drug concentration to eliminate the pathogen or resolve the condition, promoting resistance (BNF/pharmacology).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Pharmacokinetics','Suboptimal use of a drug may lead to treatment failure due to:','Too small a dose and late treatment','Unstable route and too long an interval between doses','Unsuitable route and high incidence of drug reactions','Duration of course too short and dose too small','D','Subtherapeutic regimens contribute to antimicrobial resistance — a global public health priority. Nurses provide adherence counselling, ensure complete courses and document therapy accurately (BNF; WHO AMR guidelines).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q24: Nursing intervention for nifedipine — monitor BP ────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Cardiovascular Pharmacology','One nursing intervention for a patient on nifedipine is:','Teach client about drug dosage','Monitor blood pressure','Establish safety precautions for falls','Increase the drug dose if BP remains high','B','Nifedipine lowers blood pressure by vasodilation; the primary nursing action is monitoring BP before and after administration to detect hypotension (Brunner & Suddarth; BNF).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','Cardiovascular Pharmacology','One nursing intervention for a patient on nifedipine is:','Teach client about drug dosage','Monitor blood pressure','Establish safety precautions for falls','Increase the drug dose if BP remains high','B','BP monitoring guides nifedipine titration; nurses also assess for peripheral oedema, reflex tachycardia and grapefruit juice interaction. Dose adjustment is a prescriber role (BNF; Brunner & Suddarth).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Q25: Amoxicillin — bactericidal, inhibits cell wall synthesis ─────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','Antimicrobials','The therapeutic action of amoxicillin is:','Bactericidal, inhibits protein synthesis','Inhibits bacterial cell wall synthesis and binds to sterols','Bactericidal, inhibits cell wall synthesis','Inhibits synthesis of cell wall and binds to sterols','C','Amoxicillin is bactericidal, acting by inhibiting bacterial cell-wall synthesis through binding penicillin-binding proteins (BNF antibacterials).','easy',2018,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
